def max_path_length(v1, v2, t, d):
    dp = [[0] * (v2 + d + 1) for _ in range(t)]

    for i in range(v1, min(v2, v1 + d) + 1):
        dp[0][i] = i

    for j in range(1, t):
        for k in range(v2 - d, v2 + d + 1):
            if k >= v2 - d and k <= v2 + d:
                dp[j][k] = dp[j-1][k]
            if k > v2:
                dp[j][k] = max(dp[j][k], dp[j-1][k-1] + k)
            if k < v2:
                dp[j][k] = max(dp[j][k], dp[j-1][k+1] + k)

    return max(max(row[v2-d:v2+d+1]) for row in dp)

