def max_path_length(v1, v2, t, d):
    if v1 == v2:
        return v1 * t

    if abs(v1 - v2) > d * (t - 1):
        return -1

    max_speed = max(v1, v2)
    min_speed = min(v1, v2)

    if v1 < v2:
        return (max_speed * (t + 1) + sum(range(min_speed, max_speed))) // 2
    else:
        return (min_speed * (t + 1) + sum(range(max_speed, min_speed, -1))) // 2

